@Test
public void testIsDemarcator() {
    String snippetId = "first";
    String what = "START";
    assertTrue(SnippetReader.isDemarcator(snippetId, what, "SNIPPET START first"));
    assertTrue(SnippetReader.isDemarcator(snippetId, what, "SNIPPET start first"));
    assertTrue(SnippetReader.isDemarcator(snippetId, what, "snippet START first"));
    assertTrue(SnippetReader.isDemarcator(snippetId, what, "snippet start first"));
    assertTrue(SnippetReader.isDemarcator(snippetId, what, "<!-- START SNIPPET: first -->"));
    assertFalse(SnippetReader.isDemarcator(snippetId, what, "SNIPPET START First"));
    assertFalse(SnippetReader.isDemarcator(snippetId, what, "SNIPPET START FIRST"));
    assertFalse(SnippetReader.isDemarcator(snippetId, what, "SNIPPET START first_id"));
    assertFalse(SnippetReader.isDemarcator(snippetId, what, "SNIPPET START id_first"));
}

/**
 * Test of execute method, of class TocMacro.
 *
 * @throws MacroExecutionException if a macro fails during testing.
 */
@Test
public void testExecute() throws MacroExecutionException {
    String sourceContent = "<div><h1>h11</h1><h1>h12</h1><h2>h2</h2><h3>h3</h3><h1>h13</h1></div>";
    Xhtml5BaseParser parser = new Xhtml5BaseParser();
    Map<String, Object> macroParameters = new HashMap<>();
    macroParameters.put("section", "sec1");
    File basedir = new File("");
    SinkEventTestingSink sink = new SinkEventTestingSink();
    MacroRequest request = new MacroRequest(sourceContent, parser, macroParameters, basedir);
    TocMacro macro = new TocMacro();
    macro.execute(sink, request);
    Iterator<SinkEventElement> it = sink.getEventList().iterator();
    assertEquals("list", (it.next()).getName());
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    assertEquals("text", (it.next()).getName());
    assertEquals("link_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    assertEquals("text", (it.next()).getName());
    assertEquals("link_", (it.next()).getName());
    assertEquals("list", (it.next()).getName());
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    assertEquals("text", (it.next()).getName());
    assertEquals("link_", (it.next()).getName());
    assertEquals("list", (it.next()).getName());
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    assertEquals("text", (it.next()).getName());
    assertEquals("link_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("list_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("list_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    assertEquals("text", (it.next()).getName());
    assertEquals("link_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("list_", (it.next()).getName());
    assertFalse(it.hasNext());
    // test parameters
    parser = new Xhtml5BaseParser();
    macroParameters.put("section", "2");
    macroParameters.put("fromDepth", "1");
    macroParameters.put("toDepth", "2");
    macroParameters.put("class", "myClass");
    macroParameters.put("id", "myId");
    sink.reset();
    request = new MacroRequest(sourceContent, parser, macroParameters, basedir);
    macro.execute(sink, request);
    it = sink.getEventList().iterator();
    SinkEventElement event = it.next();
    assertEquals("list", event.getName());
    SinkEventAttributeSet atts = (SinkEventAttributeSet) event.getArgs()[0];
    assertEquals("myId", atts.getAttribute("id"));
    assertEquals("myClass", atts.getAttribute("class"));
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    event = it.next();
    assertEquals("text", event.getName());
    assertEquals("h12", event.getArgs()[0]);
    assertEquals("link_", (it.next()).getName());
    assertEquals("list", (it.next()).getName());
    assertEquals("listItem", (it.next()).getName());
    assertEquals("link", (it.next()).getName());
    event = it.next();
    assertEquals("text", event.getName());
    assertEquals("h2", event.getArgs()[0]);
    assertEquals("link_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("list_", (it.next()).getName());
    assertEquals("listItem_", (it.next()).getName());
    assertEquals("list_", (it.next()).getName());
    assertFalse(it.hasNext());
}

/**
 * Test DOXIA-366.
 *
 * @throws MacroExecutionException if a macro fails during testing.
 */
@Test
public void testTocStyle() throws MacroExecutionException {
    String sourceContent = "<div><h1>h<b>11</b></h1><h1>h<i>12</i></h1><h2>h<tt>2</tt></h2><h3>h3</h3><h1>h13</h1></div>";
    Xhtml5BaseParser parser = new Xhtml5BaseParser();
    Map<String, Object> macroParameters = new HashMap<>();
    macroParameters.put("section", "sec1");
    File basedir = new File("");
    StringWriter out = new StringWriter();
    Xhtml5BaseSink sink = new Xhtml5BaseSink(out);
    MacroRequest request = new MacroRequest(sourceContent, parser, macroParameters, basedir);
    TocMacro macro = new TocMacro();
    macro.execute(sink, request);
    assertTrue(out.toString().contains("<a href=\"#h11\">h11</a>"));
    assertTrue(out.toString().contains("<a href=\"#h12\">h12</a>"));
    assertTrue(out.toString().contains("<a href=\"#h2\">h2</a>"));
}

@Test
public void testGenerateAnchors() throws ParseException, MacroExecutionException {
    String sourceContent = "<h1>1 Headline</h1>";
    File basedir = new File("");
    Xhtml5BaseParser parser = new Xhtml5BaseParser();
    MacroRequest request = new MacroRequest(sourceContent, parser, new HashMap<>(), basedir);
    TocMacro macro = new TocMacro();
    SinkEventTestingSink sink = new SinkEventTestingSink();
    macro.execute(sink, request);
    parser.parse(sourceContent, sink);
    Iterator<SinkEventElement> it = sink.getEventList().iterator();
    AbstractParserTest.assertSinkStartsWith(it, "list", "listItem");
    SinkEventElement link = it.next();
    assertEquals("link", link.getName());
    String actualLinkTarget = (String) link.getArgs()[0];
    AbstractParserTest.assertSinkEquals(it.next(), "text", "1 Headline", null);
    AbstractParserTest.assertSinkEquals(it, "link_", "listItem_", "list_", "section1", "sectionTitle1", "text", "sectionTitle1_");
    // check html output as well (without the actual TOC)
    StringWriter out = new StringWriter();
    Sink sink2 = new Xhtml5BaseSink(out);
    parser.addSinkWrapperFactory(new CreateAnchorsForIndexEntriesFactory());
    parser.parse(sourceContent, sink2);
    assertEquals("<section><a id=\"" + actualLinkTarget.substring(1) + "\"></a>" + Markup.EOL + "<h1>1 Headline</h1>", out.toString());
}

/**
 * Pipes a full model generated by {@link SinkTestDocument} through
 * a Sink (generated by {@link #createSink(Writer)}) and a Parser
 * (generated by {@link #createParser()}) and checks if the result
 * is the same as the original model. By default, this doesn't actually
 * assert anything (use {@link #assertIdentity(boolean)} in the setUp()
 * of an implementation to switch on the test), but the two generated
 * output files, expected.txt and actual.txt, can be compared for differences.
 *
 * @throws IOException if there's a problem reading/writing a test file.
 * @throws ParseException if a model cannot be parsed.
 */
@Test
public void testIdentity() throws IOException, ParseException {
    // generate the expected model
    StringWriter writer = new StringWriter();
    Sink sink = new TextSink(writer);
    SinkTestDocument.generate(sink);
    sink.close();
    expected = writer.toString();
    // write to file for comparison
    try (Writer fileWriter = getTestWriter("expectedTextSink")) {
        fileWriter.write(expected);
    }
    // generate the actual model
    writer = new StringWriter();
    sink = createSink(writer);
    SinkTestDocument.generate(sink);
    sink.close();
    String expectedViaTargetSink = writer.toString();
    // write to file for comparison
    try (Writer fileWriter = getTestWriter("expectedTargetSink")) {
        fileWriter.write(expectedViaTargetSink);
    }
    StringReader reader = new StringReader(expectedViaTargetSink);
    writer = new StringWriter();
    sink = new TextSink(writer);
    Parser parser = createParser();
    parser.parse(reader, sink);
    String actual = writer.toString();
    // write to file for comparison
    try (Writer fileWriter = getTestWriter("actualTextSink")) {
        fileWriter.write(actual);
    }
    // Disabled by default, it's unlikely that all our modules
    // will pass this test any time soon, but the generated
    // output files can still be compared.
    if (assertIdentity) {
        // TODO: make this work for at least apt and xdoc modules?
        assertEquals(getExpected(), actual, "Identity test failed! See results in " + getTestWriterFile("actual").getParent());
    }
}

